fn stack(id: &'static str, count: i32) -> Option<ItemStack> {
    let key = Identifier::new_static("minecraft", id);
    REGISTRY
        .items
        .by_key(&key)
        .map(|item| ItemStack::with_count(item, count))
}

/// Appends every generated level >= 2 offer unlocked by `requested_level`.
pub fn append_level_offers(path: &str, requested_level: i32, out: &mut Vec<MerchantOffer>) {
    for entry in TRADES {
        if entry.profession != path || entry.level > requested_level {
            continue;
        }
        let mut wants = Vec::with_capacity(entry.wants.len() + usize::from(entry.additional_wants.is_some()));
        let mut ok = true;
        for (id, count) in entry.wants {
            match stack(id, *count) {
                Some(stack) => wants.push(stack),
                None => {
                    ok = false;
                    break;
                }
            }
        }
        if ok && let Some((id, count)) = entry.additional_wants {
            match stack(id, count) {
                Some(stack) => wants.push(stack),
                None => ok = false,
            }
        }
        if !ok {
            continue;
        }
        let Some(gives) = stack(entry.gives.0, entry.gives.1) else {
            continue;
        };
        out.push(MerchantOffer {
            wants,
            gives,
            max_uses: entry.max_uses,
            uses: 0,
            xp: entry.xp,
        });
    }
}
